-- Extended demo dataset (~50 hotels total with V2). Safe to run once.


SELECT r.id, CURRENT_DATE + s.n, 4, 4
FROM rooms r
JOIN hotels h ON h.id = r.hotel_id
CROSS JOIN generate_series(0, 90) AS s(n)
WHERE h.name IN ('Istanbul Grand Hotel #1', 'Istanbul Plaza Hotel #2', 'Istanbul Garden Hotel #3', 'Istanbul Marina Hotel #4', 'Istanbul Central Hotel #5', 'Istanbul Palace Hotel #6', 'Istanbul Premium Hotel #7', 'Istanbul Suit Hotel #8', 'Istanbul Park Hotel #9', 'Istanbul Riverside Hotel #10', 'Ankara Grand Hotel #11', 'Ankara Plaza Hotel #12', 'Ankara Garden Hotel #13', 'Ankara Marina Hotel #14', 'Ankara Central Hotel #15', 'Izmir Grand Hotel #16', 'Izmir Plaza Hotel #17', 'Izmir Garden Hotel #18', 'Izmir Marina Hotel #19', 'Izmir Central Hotel #20', 'Antalya Grand Hotel #21', 'Antalya Plaza Hotel #22', 'Antalya Garden Hotel #23', 'Antalya Marina Hotel #24', 'Antalya Central Hotel #25', 'Bursa Grand Hotel #26', 'Bursa Plaza Hotel #27', 'Bodrum Grand Hotel #28', 'Bodrum Plaza Hotel #29', 'Bodrum Garden Hotel #30', 'Fethiye Grand Hotel #31', 'Fethiye Plaza Hotel #32', 'Marmaris Grand Hotel #33', 'Marmaris Plaza Hotel #34', 'Trabzon Grand Hotel #35', 'Trabzon Plaza Hotel #36', 'Gaziantep Grand Hotel #37', 'Gaziantep Plaza Hotel #38', 'Konya Grand Hotel #39', 'Konya Plaza Hotel #40', 'Nevsehir Grand Hotel #41', 'Nevsehir Plaza Hotel #42', 'Canakkale Grand Hotel #43', 'Adana Grand Hotel #44', 'Adana Plaza Hotel #45', 'Denizli Grand Hotel #46', 'Denizli Plaza Hotel #47', 'Eskisehir Grand Hotel #48', 'Rize Grand Hotel #49', 'Mersin Grand Hotel #50', 'Kayseri Grand Hotel #51');